function useSendMessage(conversationId) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (text) => api.post(`/conversations/${conversationId}/messages`, { text }),
    onMutate: (text) => {
      const temp = { id: `temp-${Date.now()}`, text, status: 'sending' };
      queryClient.setQueryData(['messages', conversationId], (old = []) => [...old, temp]);
      return { tempId: temp.id };
    },
    onSuccess: (saved, text, { tempId }) => {
      queryClient.setQueryData(['messages', conversationId], (old = []) =>
        old.map((m) => (m.id === tempId ? { ...saved, status: 'sent' } : m)));
    },
    onError: (err, text, { tempId }) => {
      queryClient.setQueryData(['messages', conversationId], (old = []) =>
        old.map((m) => (m.id === tempId ? { ...m, status: 'failed' } : m)));
    },
  });
}
